def get_recommendations(missing_skills: list[str]) -> list[dict]:
    recommendations = []
    for skill in missing_skills:
        suggestion, url = RECOMMENDATIONS.get(
            skill,
            ("Start with a beginner guide, then build a small project to practise this skill.",
             "https://www.google.com/search?q=" + skill.replace(" ", "+") + "+official+tutorial"),
        )
        high_priority = skill in {"Python", "SQL", "Git", "Data Structures", "Algorithms"}
        recommendations.append({
            "skill": skill,
            "priority": "High" if high_priority else "Medium",
            "suggestion": suggestion,
            "url": url,
        })
    return recommendations
